PRAGMA foreign_keys=ON;
CREATE TABLE commerce_carts(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchants(id),customer_id TEXT,guest_token_hash TEXT,status TEXT NOT NULL DEFAULT 'active',currency TEXT NOT NULL DEFAULT 'TWD',expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,id));
CREATE TABLE commerce_cart_items(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,cart_id TEXT NOT NULL,variant_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 999),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(cart_id,variant_id),FOREIGN KEY(merchant_id,cart_id) REFERENCES commerce_carts(merchant_id,id),FOREIGN KEY(merchant_id,variant_id) REFERENCES commerce_product_variants(merchant_id,id));
CREATE TABLE commerce_checkout_sessions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,cart_id TEXT NOT NULL,customer_id TEXT,status TEXT NOT NULL DEFAULT 'open',idempotency_key TEXT NOT NULL,expires_at TEXT NOT NULL,terms_version TEXT NOT NULL,consented_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key),FOREIGN KEY(merchant_id,cart_id) REFERENCES commerce_carts(merchant_id,id));
CREATE TABLE commerce_orders(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchants(id),order_no TEXT NOT NULL,customer_id TEXT,channel TEXT NOT NULL DEFAULT 'web',status TEXT NOT NULL DEFAULT 'pending_payment' CHECK(status IN('draft','pending_payment','paid','confirmed','processing','partially_shipped','shipped','delivered','completed','cancelled','return_requested','partially_refunded','refunded')),currency TEXT NOT NULL DEFAULT 'TWD',subtotal_minor INTEGER NOT NULL,discount_minor INTEGER NOT NULL DEFAULT 0,shipping_minor INTEGER NOT NULL DEFAULT 0,tax_minor INTEGER NOT NULL DEFAULT 0,total_minor INTEGER NOT NULL,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,order_no),UNIQUE(merchant_id,idempotency_key),UNIQUE(merchant_id,id),CHECK(total_minor=max(subtotal_minor-discount_minor+shipping_minor+tax_minor,0)));
CREATE TABLE commerce_order_items(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT NOT NULL,product_id TEXT NOT NULL,variant_id TEXT NOT NULL,sku_snapshot TEXT,title_snapshot TEXT NOT NULL,unit_price_minor INTEGER NOT NULL,quantity INTEGER NOT NULL,line_total_minor INTEGER NOT NULL,FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_order_pricing_snapshots(order_id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,pricing_json TEXT NOT NULL,calculation_version TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_order_status_history(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT NOT NULL,from_status TEXT,to_status TEXT NOT NULL,actor_type TEXT NOT NULL,actor_id TEXT,reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_order_adjustments(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT NOT NULL,kind TEXT NOT NULL,amount_minor INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_order_transactions(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT NOT NULL,kind TEXT NOT NULL,amount_minor INTEGER NOT NULL,status TEXT NOT NULL,provider TEXT,provider_reference TEXT,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,idempotency_key),FOREIGN KEY(merchant_id,order_id) REFERENCES commerce_orders(merchant_id,id));
CREATE TABLE commerce_order_audit_logs(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL,order_id TEXT,action TEXT NOT NULL,actor_type TEXT NOT NULL,actor_id TEXT,metadata TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER trg_order_pricing_immutable_update BEFORE UPDATE ON commerce_order_pricing_snapshots BEGIN SELECT RAISE(ABORT,'pricing snapshot immutable'); END;
CREATE TRIGGER trg_order_pricing_immutable_delete BEFORE DELETE ON commerce_order_pricing_snapshots BEGIN SELECT RAISE(ABORT,'pricing snapshot immutable'); END;
CREATE INDEX idx_orders_merchant_status ON commerce_orders(merchant_id,status,created_at);
